export function cartTotal(cart) {
  return cart.items
    .map(itemTotal)
    .reduce((a, b) => a + b, 0)
}

function itemTotal(item) {
  const product = catalog.find(item.productId)
  // 依數量與會員等級計算小計
  const qty = item.qty
  const rate = item.vip ? 0.9 : 1
  return Math.round(product.price * qty * rate)
}

